    let mut score = post_residual as f64 ;
    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 10 {
        score -= 200.0 - (post_residual as f64) * 10.0 ;
    } else {
        let r = post_residual ;
        let harmonic_bonus : f64 = if r % 50 == 0 { 150.0 } else if r % 25 == 0 { 100.0 } else if r % 10 == 0 { 75.0 } else if r % 5 == 0 { 40.0 } else { 0.0 } ;
