pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance with quadratic penalty below minimum usable residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 12.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    } else if post_residual > 50 {
        score -= 35.0;
    }

    // Harmonic residual bonuses: leave round residuals for future items.
    let r = post_residual;
    let harmonic_bonus: f64 = if r % 50 == 0 { 160.0 } else if r % 25 == 0 { 105.0 } else if r % 10 == 0 { 80.0 } else if r % 5 == 0 { 45.0 } else { 0.0 };
    score -= harmonic_bonus;

    // Nonlinear fit tightness term.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 9.0 * fit_ratio * fit_ratio;

    // Lookahead with quadratic dead-space growth.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += 4.0 * dead + 2.0 * dead * dead / (next_item_size as f64).max(1.0);
        } else if post_residual == next_item_size {
            score -= 135.0;
        } else {
            let second_gap = post_residual - next_item_size;
            let mut bonus = 4.0;
            if second_gap <= 20 {
                bonus += 15.0;
            }
            score -= bonus;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling with fragmentation and progress pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let next_pressure = (next_item_size as f64 / bin_capacity as f64).clamp(0.0, 1.0);
        score += 25.0 - 15.0 * fragmentation - 9.0 * progress + 6.0 * next_pressure;
        if item_size > 60 {
            score -= 15.0;
        }
    }

    // Residual balancing toward mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.04 * dev;

