    score *= 1.0 + 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with superlinear penalty on large waste.
    score += 0.02 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nx {
            let gap = pr - nx;
            // Perfect match for the next item is highly desirable.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            score -= 0.05 * gap; // small extra reward for close matches
        } else {
            // Next item cannot fit here: penalize proportionally to how far off we are.
            score += 8.0 * (nx - pr) / bin_capacity as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious; using them
    // on a loose fit wastes them, but finishing them off is good.
    let mr = mean_residual;
    if mr > 0.0 {
        let rel = (bin_residual as f64) / mr;
        if rel < 1.0 {
            // Below-average residual bin: reward placement that leaves small post_residual.
            score -= 6.0 * (1.0 - rel) * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // Above-average residual bin: tolerate more waste here.
            score -= 2.0 * (rel - 1.0).min(2.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the item
    // is large relative to capacity and no open bin fits well.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        // Penalize opening new bins generally; less so for large items.
        score += 30.0 - 20.0 * fill;
        // If the next item would fit nicely in the fresh bin's leftover, soften the penalty.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            let gap = (bin_capacity - item_size - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        }
        // Fewer open bins means new bins are cheaper to open.
        score -= 1.5 * open_bins_count as f64;
    } else {
        // Mild reward for keeping the number of open bins high but consolidated.
        score += 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Stream progression: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

