pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0 - (post_residual as f64) * 10.0;
    } else {
        let r = post_residual;
        let harmonic: f64 = if r % 50 == 0 { 155.0 }
            else if r % 25 == 0 { 105.0 }
            else if r % 10 == 0 { 80.0 }
            else if r % 5 == 0 { 45.0 }
            else { 0.0 };
        score -= harmonic;
        if r > 50 { score -= 35.0; }
        else if r < 15 { score += 55.0; }

        // dead-ratio shaping: reward bins whose fill fraction is high
        let consumed = item_size as f64;
        let dead_ratio = (r as f64) / (consumed + r as f64 + 1.0);
        score += 30.0 * dead_ratio * dead_ratio;

        // penalize residuals too large to pair with next item but too small to be useful
        if next_item_size > 0 && r > next_item_size {
            let gap = (r - next_item_size) as f64;
            if gap <= 25.0 {
                score += 0.45 * gap * (1.0 - 0.6 * progress);
            }
        }
        // reward near-perfect two-item pairings
        if next_item_size > 0 && r >= next_item_size && r <= next_item_size * 2 {
            score -= 10.0;
        }
        // half/third capacity sweet spots
        let half_cap = bin_capacity / 2;
        if r > half_cap && r <= half_cap + 8 { score += 7.0; }
        let third_cap = bin_capacity / 3;
        if r > third_cap && r <= third_cap + 5 { score += 4.0; }
        // exact next-item match with few alternatives
        if next_item_size > 0 && r == next_item_size && fitting_bins_count <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 140.0;
        } else if post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += 4.0 * dead + 2.0 * dead * dead / (next_item_size as f64).max(1.0);
        } else {
            let gap = post_residual - next_item_size;
            let mut bonus = 4.0;
            if gap <= 20 { bonus += 15.0; }
            if gap <= next_item_size as u32 * 2 { bonus += 6.0; }
            if gap <= 6 && post_residual <= bin_capacity / 3 { bonus += 8.0; }
            bonus -= 5.0 * progress * ((gap as f64) / 20.0).min(1.0);
            score -= bonus;
            let slack = gap as f64;
            score -= 12.0 / (1.0 + slack * 0.15);
        }
    }

    if post_residual > 0 && post_residual < 10 {
        score += 120.0 * (1.0 - progress);
    }
    if post_residual > 0 && post_residual <= 3 {
        score -= 30.0 * (0.5 + progress);
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate decision
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let next_pressure = (next_item_size as f64 / bin_capacity as f64).clamp(0.0, 1.0);
        score += 70.0 - 25.0 * fragmentation - 20.0 * progress + 12.0 * next_pressure;
        if next_item_size > 0 && next_item_size > post_residual.max(1) && fitting_bins_count <= 1 {
            score -= 110.0;
        }
    } else {
        score -= 40.0 * progress;
    }

    score -= 0.5 * (mean_residual - post_residual as f64);
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.04 * dev;

    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 0.02 * open_bins_count as f64 * (1.0 - fit_ratio);
    score += 6.0 * fit_ratio * fit_ratio;

    score
}

