    }

    // Time horizon: early in the stream, be conservative (prefer tight fits);
    // late in the stream, favor consolidating into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - pr / bin_capacity as f64);
    score += 15.0 * (1.0 - progress) * (pr / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins
    let mean_r = mean_residual / bin_capacity as f64;
    score -= 0.5 * mean_r * open_bins_count as f64 * (pr / bin_capacity as f64);
    if open_bins_count > 8 && mean_r > 0.4 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no good fit exists (large post_residual elsewhere
    // would be wasted anyway) or stream is early and mean residual is low.
    if bin_residual == bin_capacity {
        let waste_threshold = 35.0 + 30.0 * (1.0 - progress);
        if pr.min(100.0) > waste_threshold || (fitting_bins_count == 0) {
            score -= 30.0;
        } else {
            score += 45.0 + 20.0 * mean_r;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on post-residual, scaled by stream progress
    let mut score = pr * (1.0 + 1.5 * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Smooth interaction: prefer tight fits more strongly as stream progresses
    score -= 30.0 * norm_item * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize post-residual that can't fit the lookahead item (smooth soft margin)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 25.0 * gap * gap * (1.0 + progress);
        // Reward residuals that still fit the next item
        let fits_next = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 10.0 * fits_next * (1.0 - progress);
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr) + 10.0 * progress;
    }

    // Mild penalty when this bin deviates from mean residual (keep bins balanced)
    score += 0.3 * (pr - mean_residual).abs();

    // Slight nudge toward consolidating into fewer bins early on
    score += 2.0 * (open_bins_count as f64 / (1.0 + progress * 10.0)) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes modulo capacity/10.
    let class_width = (bin_capacity / 10).max(1); // 10 for C=100
    let post_class = (post_residual / class_width) as f64; // 0..10
    let item_class = (item_size / class_width) as f64;

    // Dead-space penalty: residuals too small for the smallest items (<=10) are dead.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual == 10 {
        // Perfect harmonic closure: residual exactly fits a minimum item.
        score -= 45.0;
    } else if post_residual < 2 * class_width {
        // Residual 11..19: only usable by tiny items; risky dead space.
        score += 18.0;
    }

    // Reward residuals that are exact multiples of the class width (harmonic bins).
    if post_residual % class_width == 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 25.0; // near-perfect chain fit
            } else {
                score -= (20.0 - post_class.min(20.0)) * 0.5;
            }
        } else {
            // Next item cannot use this bin's remainder: mild penalty scaled by
            // how small the leftover is relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / class_width as f64).min(4.0) * 6.0;
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer tighter bins generally: scale by how full the bin already is.
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fullness * 15.0;

    // Penalize opening a new bin when good fitting bins exist; new-bin candidate
    // (bin_residual == bin_capacity) gets a baseline handicap unless stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 - 15.0 * progress;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.8;

    // Mean-residual coupling: if this bin's residual is far below mean, it's a
    // "harmonic outlier" — placing here reduces fragmentation of large residuals.
    let res_f = post_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f).min(50.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Reward near-exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // If lookahead item fits the post residual, this placement is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit in the leftover, penalize slightly more when gap is tiny.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Mild preference for tighter-than-average bins.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Late in the stream, avoid leaving any residual at all costs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 30.0 + open_bins_count as f64 * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 50.0 + 100.0 * tightness;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space relative to next item size.
        let gap = post_residual as f64 - (next_item_size as f64).min(post_residual as f64);
        score += gap * 0.5;
    }

    // Penalize small unusable residuals (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer bins tighter than the mean residual (concentrate waste in few bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in stream: be greedier about filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 * (next_item_size - post_residual) as f64;
        } else {
            // Bonus if this placement still accommodates the next item.
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for competing with many alternatives unless very tight.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: opening a new bin is costly early, acceptable later.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        // Prefer new bin only if existing bins are fragmented and it's late in stream.
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 20.0 - 14.0 * fragmentation - 8.0 * progress;
    }

    // Encourage balancing residuals toward mean (avoid extreme skew).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild pressure to close nearly-full bins to reduce open-bin count.
    score -= 0.02 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Time-horizon term: as stream progresses, value compactness more.
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize very small post-residuals more as the stream progresses (dead space).
    score += (norm_pr * norm_pr) * 30.0 * (0.5 + progress);

    // Reward tight fits, stronger later in the stream.
    score -= (item_size as f64 / cap) * 20.0 * (0.3 + 0.7 * progress);

    // Last-chance bin bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && post_residual as i64 == next_item_size as i64 {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mild penalty for wasting space.
        score += norm_pr * 10.0 * progress;
    }

    // New-bin candidate handling: make empty bins attractive early, less so late.
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.5 * progress) - (item_size as f64 / cap) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (capacity fractions / modulo classes) ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1 capacity fraction left over

    // Perfect fits are gold: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic residue classes: residuals that are "reusable" by common item sizes
    // (multiples of 10, 20, 25, 50 within 1..100) are more valuable than odd leftovers.
    let r = post_residual;
    let harmonic_bonus: f64 = if r == 0 {
        0.0
    } else if r % 50 == 0 {
        12.0
    } else if r % 25 == 0 {
        9.0
    } else if r % 20 == 0 {
        8.0
    } else if r % 10 == 0 {
        6.0
    } else if r % 5 == 0 {
        3.0
    } else {
        -2.0 // odd dead space is penalized
    };
    score -= harmonic_bonus;

    // Dead-space penalty: residuals too small for the smallest plausible item (size 1)
    // are worthless; anything below ~10 is nearly dead.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Coupling with lookahead: if the next item fits exactly into post_residual,
    // this bin becomes a perfect two-item chain -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after next placement
            let post2 = post_residual - next_item_size;
            score -= 10.0 + (post2 % 10 == 0) as i32 as f64 * 8.0;
        } else {
            // next item cannot use this residual: residual is a dead end for lookahead
            let gap = next_item_size - post_residual;
            score += (gap as f64).min(40.0) * 0.4;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + frac * 10.0;
    }

    // New-bin candidate handling: an empty bin has max residual. Make it a fallback:
    // prefer existing bins with reasonable fits, but allow new bin when existing fits
    // create lots of dead space (score already high) or few bins are open early.
    if bin_residual == bin_capacity {
        // neutral-ish baseline plus mild pressure against opening bins too eagerly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 - 10.0 * progress;
    }

    // Tightness reward: bins that end up nearly full are good.
    score -= (1.0 - frac) * 5.0;

    // Slight preference to fill bins with lower mean residual (balance consolidation).
    score += (mean_residual - post) * 0.05;

    // Modulo threshold on item_size: large items (>= half capacity) prefer tight bins.
    if item_size >= bin_capacity / 2 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable
    // (item sizes span 1..100), so they are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 9 {
            score += 40.0 * (10.0 - post_residual as f64);
        } else if post_residual <= 19 {
            score += 12.0;
        } else if post_residual <= 29 {
            score += 4.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward leaving room for the lookahead item if it fits exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // leftover blocks the known next item
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // a new empty bin should only win when the fit is terrible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline around mean residual, penalized by pressure.
        score = bin_capacity as f64 - 20.0 + pressure * 3.0 + mean_residual * 0.1;
    } else {
        // Existing bins get a discount scaled by open-bin pressure.
        score -= pressure;
        // Slight preference for bins tighter than average.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: prefer tight fits (low post_residual) with a mild nonlinearity.
    score += 0.15 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // 2-step lookahead: strongly reward bins where the NEXT item also fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tightness = (post_residual - next_item_size) as f64;
            score -= 40.0 + 0.5 * next_item_size as f64 - 0.3 * next_tightness;
        } else {
            // Next item won't fit here: penalize proportionally to the shortfall,
            // but soften if the leftover is small (still a good single fit).
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.4 * shortfall;
        }
    }

    // Compare against mean residual: placing into a bin far from the mean
    // residual can unbalance the pool; mildly pull score toward that judgment.
    score += 0.1 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than
    // spreading out; scale a small bonus with open bin count.
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64;
    }

    // Early in the stream, allow opening new bins more freely (keep fresh
    // bins attractive); later, penalize new bins to force tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no typical item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: reward if the next item fits in the post-residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0;
        } else {
            // penalize blocking the next item badly
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.25 * waste;
        }
    }

    // Global state: when many bins are open with high mean residual, prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins exist and mean residual
        // is sufficient to absorb the item.
        let mut new_bin_penalty = 15.0 + 20.0 * progress;
        if open_bins_count > 0 {
            if mean_residual >= item_size as f64 {
                new_bin_penalty += 10.0 + 0.5 * (mean_residual - item_size as f64).min(40.0);
            }
        }
        // Exception: allow a new bin early in the stream to build diversity.
        if open_bins_count == 0 {
            new_bin_penalty -= 40.0;
        }
        score += new_bin_penalty;
    } else {
        // Mild reward for using existing bins when fragmentation is high.
        score -= 0.05 * open_bins_count as f64;
    }

    // Time-horizon effect: late in the stream, be conservative, prefer exact fills.
    score -= 8.0 * progress * tightness;

    // Prefer bins whose residual is close to the item (best-fit flavor with
    // dynamic scaling by mean residual).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;
    score -= 0.1 * (bin_residual as f64 - mean_residual).abs().min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post-residual in [0,1]

    // Base: penalize post-residual, with non-linear curvature.
    let mut score = post * (1.0 + 0.5 * x * x);

    // Quadratic coupling: as stream progresses, prefer tighter fits more strongly.
    let progress_tightening = progress * post * post / cap;
    score += 1.5 * progress_tightening;

    // Cubic interaction: dead space becomes increasingly costly late in the stream.
    score += 2.0 * progress * progress * x * x * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits into post-residual (chaining placements).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= post {
            score -= 8.0 * (1.0 - (post - ni) / cap);
        } else {
            // penalize leaving residual that next item can't use
            score += 4.0 * (ni - post) / cap;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below mean, its space is scarce -> prefer using it.
    let dev = (mean_residual - bin_residual as f64) / cap;
    score -= 3.0 * dev;

    // Mild penalty for spreading across many open bins (encourage consolidation).
    score += 0.05 * open_bins_count as f64 * x;

    // New-bin candidate: make empty bin mildly unattractive unless residual would be perfect.
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bucket dead space by capacity/8 slices.
    let class = post_residual / (bin_capacity / 8).max(1);
    score += class as f64 * 3.0;

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Small leftover that many future items can still use is fine; large leftover
    // in the "useless" band (just above typical item sizes) is penalized.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }
    if post_residual >= 60 {
        score += 6.0; // dead-ish space band
    }

    // Modulo coupling: leftover that is an exact complement to common item classes
    // (multiples of 10) is more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when this bin would leave bad residue
    // or when the bin is nearly full already.
    if bin_residual == bin_capacity {
        score = cap * 0.55; // neutral-ish baseline for a fresh bin
        if post_residual < 20 { score -= 15.0; } // big item starting fresh bin
        if next_item_size > 0 && next_item_size <= post_residual { score -= 10.0; }
        if open_bins_count == 0 { score -= 50.0; }
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (post_residual as f64 / cap);

    // Slight preference for bins with below-average residual (fill emptier bins first).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
