pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward (score 0 effectively unbeatable)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills the post residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits here: mild reward proportional to how snugly it fits
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot fit in leftover: penalize dead space that blocks lookahead
            score += 30.0 * (1.0 - (next_item_size as f64 / (bin_capacity as f64)));
        }
    }

    // Penalize small unusable residuals (dead space < 10, minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's clearly better
    if bin_residual == bin_capacity {
        score += 80.0;
        // If next item is large and no good fit exists, opening new bin becomes attractive
        if next_item_size > 0 && next_item_size > post_residual.max(1) && fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Prefer tighter bins relative to mean residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Late in stream: be more conservative with new bins, prefer filling existing
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 60.0 * progress;
    } else {
        score -= 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but dead space below
    // the minimum item size is worthless.
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual < 20 {
        score -= 6.0;
    }

    // Penalize leaving residuals that no plausible item can use well.
    if post_residual > 60 {
        score += 8.0;
    } else if post_residual > 40 {
        score += 3.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size as f64 <= post_residual as f64 {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize proportionally to waste
            score += (next_item_size as f64 - post_residual as f64).min(10.0) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
        if post_residual < 20 {
            score -= 6.0;
        }
    }

    // New-bin candidate logic: an empty bin should only win when existing bins
    // offer poor fits. Give empty bins a moderate handicap so tight fits win.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, opening bins is cheaper (more items to come to fill them);
        // late in the stream, prefer consolidating into existing bins.
        score += 10.0 - 6.0 * progress;
        // If many bins are open with slack, discourage yet another bin.
        score += (open_bins_count as f64).sqrt() * 1.5;
        // If mean residual is high, existing bins have room: penalize new bin.
        score += (mean_residual / 20.0).min(8.0);
    }

    // Slight preference for fuller bins relative to the average open bin.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Fragmentation penalty: residual that is awkward relative to item size.
    let ratio = item_size as f64 / bin_residual as f64;
    if ratio > 0.9 {
        score -= 10.0;
    } else if ratio > 0.7 {
        score -= 4.0;
    } else if ratio < 0.3 && bin_residual < bin_capacity {
        score += 4.0; // dumping a small item into a big bin wastes it
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: post residual, with smooth non-linear shaping over stream progress.
    let mut score = r * (1.0 + 0.6 * progress * rn * rn);

    // Reward tight fits: quadratic coupling of fill ratio with progress.
    let fill = item_size as f64 / cap;
    score -= cap * fill * fill * (0.5 + 0.5 * progress);

    // Penalize dead space that is too small to be useful later (smooth threshold via sigmoid-like term).
    let dead = rn * (1.0 - rn);
    score += 8.0 * dead * (1.0 - 2.0 * rn) * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - rn);
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let gap = (r - (item_size as f64 + next_item_size as f64)) / cap;
        score -= 6.0 * gap.max(0.0) - 4.0 * (-gap).max(0.0);
    }

    // Mild pressure toward consolidation when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * rn * 2.0;

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic).
    score += 0.15 * (r - mean_residual) * (r - mean_residual) / cap;

    // New-bin candidate: keep neutral baseline so it competes fairly.
    if bin_residual == bin_capacity {
        score = cap * 0.45 - 20.0 * progress + 0.3 * (item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible by 10 -> leaves "clean" harmonic slots.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Class B: post_residual divisible by 25 -> quarter/half capacity harmony.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Class C: tiny dead space (1..=5) is nearly unusable for items >= 10... but
    // interface allows items >= 1, so penalize only very small slivers.
    if post_residual > 0 && post_residual < 3 {
        score += 20.0;
    }

    // Integer-division threshold: post_residual / next_item_size couplings.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Exact harmonic fit: next item exactly consumes the residual.
            if next_item_size == post_residual {
                score -= 25.0;
            } else {
                // How many times next item divides into post residual.
                let k = (post_residual / next_item_size) as f64;
                score -= 6.0 * k.min(4.0);
                // Residual after next item: harmonic class again.
                let post2 = post_residual - next_item_size;
                if post2 % 10 == 0 {
                    score -= 5.0;
                }
                if post2 < 3 {
                    score += 10.0;
                }
            }
        } else {
            // Next item cannot use this bin's residual: dead space risk.
            score += 0.05 * nxt;
        }
    }

    // Capacity fraction coupling: reward filling toward full capacity.
    let fill_frac = (item_size as f64) / cap;
    score -= 10.0 * fill_frac * fill_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin early in the stream or when open bins are already crowded.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.1 && open_bins_count < 3 {
            score -= 20.0;
        }
        if mean_residual < 10.0 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.1 * (post - mean_residual);

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

