    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: does the leftover space accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainable: reward proportionally to how well next item fits the leftover
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 30.0 * chain_fit;
