            if post_residual == next_item_size {
                score -= 60.0;
            }
        } else {
            // Leftover too small for next item: penalize dead space sized below next_item_size.
            // Amplify the penalty when the dead space is large relative to the item
            // (wasting a big hole on a small item is worse than a tiny hole).
            let dead_ratio = 1.0 - post_residual as f64 / next_item_size as f64;
            score += 25.0 * dead_ratio + 20.0 * dead_ratio * dead_ratio;
        }
    }

    // Prefer using bins with above-average residual (keep tight bins for later),
    // scaled by how many alternatives exist: with few fitting bins, residual
    // balance matters less than just placing the item.
    let residual_diff = bin_residual as f64 - mean_residual;
    let alt_scale = if fitting_bins_count > 1 { 0.15 } else { 0.05 };
    score += alt_scale * residual_diff;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Base penalty grows with the fraction of
    // the capacity that would be wasted by this item alone.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = item_size as f64 / bin_capacity as f64;
        // Small items in a fresh bin waste most of it: penalize harder.
        // Large items (>60% of capacity) deserve a fresh bin more readily.
        let waste_penalty = 70.0 - 40.0 * waste;
        score += waste_penalty - 15.0 * progress;

        // If next item is large and the fresh bin can host both, opening is attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 45.0;
            // Extra attraction when the pair nearly fills the bin
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill > 0.9 {
                score -= 30.0;
            }
        }

        // If several open bins already fit, a new bin is rarely justified
        if fitting_bins_count > 2 {
            score += 25.0;
        }
    }

    // Mild penalty for scattering across many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

