            score += (20.0 - gap) * (20.0 - gap) * 0.8;
        } else if gap < 35.0 {
            // risky small gap
            score += (35.0 - gap) * 1.5;
        }
    } else {
        // perfect fit: big reward
        score -= 60.0;
    }

    // Reward tight fits generally: prefer bins where item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: with many open bins, discourage opening new ones.
    // If this is a new empty bin (bin_residual == bin_capacity), penalize
    // proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.5;
    } else {
        // mild reward for using existing bins, stronger when many are open
        score -= 3.0 + open_bins_count as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit in the gap: penalize large wasted gaps
            score += gap * 0.2;
        }
    }

    // Mean residual coupling: prefer bins close to the mean residual
    // (balanced packing keeps more bins usable).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // Slight stream-position term: early on, be a bit more conservative
    // about opening bins; late, allow tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
