            score += 0.3 * chain_waste;
        } else {
            // next item won't fit here; if this bin is the last chance, prefer using it now
            if fitting_bins_count == 1 {
                score -= 80.0;
            }
        }
    }

    // Last-chance bin pressure: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        // base penalty for new bin
        score += 40.0;
        // if many bins fit the item already, discourage new bin more
