    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact division classes of capacity.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Perfect-fit reward: post_residual exactly 0 is ideal.
    if pr == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: residuals that are multiples of common item sizes (10,20,25,50)
    // are "reusable" classes; non-harmonic residuals are dead space.
