            150.0
        } else if r % 25 == 0 {
            100.0
        } else if r % 10 == 0 {
            75.0
        } else if r % 5 == 0 {
            40.0
        } else {
            0.0
        };
        score -= harmonic_bonus;
        // Penalize large awkward residuals less than tiny awkward ones.
        if r > 50 {
            score -= 30.0; // big residual likely refillable later
        } else if r < 15 {
            score += 50.0; // small dead zone
        }
    }

