    // no open bin offers a decent fit. Empty-bin call has bin_residual == cap.
    if bin_residual == bin_capacity {
        // Base cost of a new bin; make it comparable to a mediocre placement.
        score = cap * 0.6;
        // If item is large, a fresh bin wastes little; encourage a bit.
        if item_size as f64 > cap * 0.5 {
            score -= 20.0;
