        } else if nxt <= post {
            // Next item fits: reward proportional to tightness of the chain.
            score -= 25.0 * (1.0 - diff / post.max(1.0));
        } else {
            // Next item does NOT fit into this bin's leftover: penalize
            // large leftover dead space that the next item can't use.
            score += 10.0 * (1.0 - post / bin_capacity as f64);
        }

        // Coupling with mean residual: if this bin's post_residual deviates
        // strongly below the mean, it's a well-packed bin — reward it.
        let mean_dev = (mean_residual - post) / (bin_capacity as f64);
        score -= 8.0 * mean_dev;

        // If next item is large and only barely fits elsewhere, prefer
        // conserving bins with big residuals for it.
        if nxt > post {
            score += 6.0 * (nxt - post) / bin_capacity as f64;
        }
    } else {
        // Last item: just minimize waste directly.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // using it avoids opening a new bin — strong reward unless waste is huge.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio < 0.5 {
            score -= 30.0 * (1.0 - waste_ratio);
        } else {
            score -= 5.0;
        }
    }

    // Penalize spreading across many open bins late in the stream
    // (encourages consolidation when few items remain).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (open_bins_count as f64).ln().max(0.0) / 10.0;

    // New-bin candidate: only attractive when current item is huge relative
    // to all residuals or no open bin fits well. Penalize opening new bins
    // mildly so existing bins are preferred on decent fits.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the item is very large, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Mild preference for tighter fits overall (small post_residual wins).
    score += 0.05 * post_residual as f64;

    score
}

