        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // Many open bins with high mean residual: prefer using them instead
        score += 0.5 * open_bins_count as f64;
        if mean_residual > (item_size as f64) {
            score += 5.0;
        }
        // Small items: cheap to place anywhere, avoid wasting a fresh bin
        if item_size <= 30 {
            score += 15.0;
        }
    } else {
        // Reward placing into bins whose residual is close to item (best-fit flavor)
        let fit_gap = (bin_residual - item_size) as f64;
        score += 0.1 * fit_gap;
    }

    // Penalize leaving residuals in the awkward zone (e.g., 51..=70) that few items fit
    if post_residual >= 51 && post_residual <= 70 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness term: nonlinear reward for small post_residual.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 52.0 * tightness * tightness * (1.0 + 0.6 * tightness);

    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: reusable residual shapes.
    if post_residual > 0 {
        let r = post_residual;
        let harmonic_bonus: f64 = if r % 50 == 0 {
            150.0
        } else if r % 25 == 0 {
            100.0
        } else if r % 10 == 0 {
            75.0
        } else if r % 5 == 0 {
            40.0
        } else {
            0.0
        };
        score -= harmonic_bonus;
        if r > 50 {
            score -= 30.0;
        } else if r < 15 {
            score += 50.0;
        }
    }

    // Lookahead: chain-fit coupling with next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 40.0 * chain_fit;
            if post_residual == next_item_size {
                score -= 500.0;
            }
        } else {
            let dead = post_residual as f64 / next_item_size as f64;
            let fill = item_size as f64 / cap;
            score += 34.0 * (1.0 - dead) * (1.0 - dead) * (0.6 + 0.8 * fill);
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += cap * 0.6 + 78.0 - 34.0 * progress - 10.0 * fragmentation;
        if next_item_size > 0 {
            let pair = item_size + next_item_size;
            if pair == bin_capacity {
                score -= 100.0;
            } else if pair <= bin_capacity {
                let slack = (bin_capacity - pair) as f64 / cap;
                score -= 44.0 * (1.0 - slack);
            } else if next_item_size as f64 > 0.75 * cap {
                score -= 10.0;
            }
        }
        if item_size as f64 > 0.6 * cap {
            score -= 18.0;
        }
        if mean_residual > item_size as f64 + 10.0 {
            score += 60.0;
        }
        if fitting_bins_count <= 1 {
            score -= 28.0;
        }
    } else {
        // Discourage wasteful placements into roomy bins.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
            score += 20.0 * (1.0 - fill_ratio);
        }
        // Penalize residual leakage that next item cannot use.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let leak = post_residual as f64 / cap;
            score += 14.0 * leak * (1.0 + progress);
        }
        // Protect residual that next item could chain into with this item.
        if next_item_size > 0 && bin_residual >= next_item_size
            && (bin_residual - next_item_size) < (item_size.max(1) / 2).max(1)
            && item_size < next_item_size
        {
            score += 26.0;
        }
    }

    // Stream phase: late in the stream, be greedier about exactness.
    score *= 1.0 + 0.2 * progress;

    // Slight preference for bins with below-average residual (consolidate waste).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

