    } else if post <= 10 {
        score -= 45.0;
    } else if post <= 20 {
        score -= 20.0;
    } else if post <= 30 {
        score -= 8.0;
    } else {
        score += (post as f64 - 30.0) * 0.35; // dead-space penalty grows
    }

    // Modulo classes: residuals that are multiples of 10 are reusable by
    // typical item sizes; odd/awkward residuals are penalized.
    let m = post % 10;
    if m == 0 {
        score -= 6.0;
    } else if m >= 7 {
        score += 3.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // next item fits: reward proportionally to how snugly
            let slack = (post - next_item_size) as f64;
            score -= 25.0 - slack * 0.5;
        } else {
            // next item does not fit here; penalize large leftovers that
            // still cannot host the lookahead item
            score += 5.0 + (post as f64) * 0.1;
        }
        // harmonic class of next item size (integer division buckets)
        let nclass = next_item_size / 10;
        let pclass = post / 10;
        if nclass == pclass && post >= next_item_size {
            score -= 10.0; // same harmonic bucket: strong reuse chance
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new one (unless post residual would be huge).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post > 50 {
            score += 25.0; // but avoid dumping into a near-empty bin
        }
    }

    // New-bin candidate: empty bin gets a baseline score; prefer it when
    // no open bin gives a tight fit (post residual small).
    if bin_residual == bin_capacity {
        score = 55.0 + (next_item_size as f64) * 0.15;
    }

    // Late-stream consolidation: as stream progresses, favor filling
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    }

    // Slight preference for bins below the mean residual (keep spread even)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
