    // Open-bin pressure: with many bins open, prefer reusing existing bins
    // (which is implicit) but penalize opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty grows with open bins and stream progress.
        score += 30.0 + open_bins_count as f64 * 4.0 + (step_index as f64 / total_items.max(1) as f64) * 15.0;
        // Attractive if the item would leave a large, still-usable gap
