pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect match: post_residual exactly equals next item size -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too: mild reward proportional to how close the
            // combined fill is to capacity (tight two-item packing).
            let two_step_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * two_step_fill;
            // Penalize leftover slack after the hypothetical second placement,
            // scaled by how much it deviates from the fleet mean residual.
            let after_two = (post_residual - next_item_size) as f64;
            score += 0.35 * (after_two - mean_residual).abs();
        } else {
            // Next item does NOT fit after this placement: penalize dead space
            // that blocks the lookahead item.
            score += 12.0;
        }
    }

    // --- Tightness reward: smaller post_residual is generally better ---
    score -= 0.5 * (post_residual as f64 / bin_capacity as f64);

    // --- Last-chance bonus: if this is the only bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // --- Mean-residual coupling: prefer bins whose residual is below average
    //     (consolidate items into emptier-relative bins, keep average slack low) ---
    score += 0.2 * (mean_residual - post_residual as f64);

    // --- New-bin handling ---
    if is_new_bin {
        // Opening a new bin is wasteful while others fit; penalize it.
        // The penalty shrinks as the stream progresses (fewer future chances
        // to consolidate) and when many bins are open (fragmented state).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0 - 20.0 * progress;
        if open_bins_count > 0 {
            score += 10.0;
        }
        // If NO open bin fits (fitting_bins_count == 0 among open bins), the new
        // bin is the only option: cancel the penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // --- Stream progression: late in the stream, be more conservative with
    //     residual space since fewer items remain to fill gaps ---
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

