            score += 34.0 * (1.0 - dead) * (1.0 - dead) * (0.6 + 0.8 * fill);
        }
    }

    // Last-chance bin handling.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // New-bin candidate: open only when it enables a near-perfect pairing
    // with the next item, or when existing bins are hopeless.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 78.0 - 34.0 * progress - 10.0 * fragmentation;
        if next_item_size > 0 {
            let pair = item_size + next_item_size;
            if pair == bin_capacity {
                score -= 100.0;
            } else if pair <= bin_capacity {
                let slack = (bin_capacity - pair) as f64 / cap;
                score -= 44.0 * (1.0 - slack);
            } else if next_item_size as f64 > 0.75 * cap {
                score -= 10.0;
            }
        }
        if item_size as f64 > 0.6 * cap {
            score -= 18.0;
        }
        if fitting_bins_count <= 1 {
            score -= 28.0;
        }
    } else {
        // Discourage tiny items wasting large residuals.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
            score += 20.0 * (1.0 - fill_ratio);
        }
        // Penalize residual leaks that the next item cannot use.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let leak = post_residual as f64 / cap;
            score += 28.0 * leak * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Reward placements that leave a residual matching next item exactly.
        if next_item_size > 0 && bin_residual >= next_item_size
            && (bin_residual - next_item_size) < (item_size.max(1) / 2).max(1)
            && item_size < next_item_size {
            score += 26.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
            let leak = post_residual as f64 / cap;
            score += 14.0 * leak * (1.0 + progress);
        }
    }

    // Mild skew-balancing deviation penalty.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time-horizon: value compactness more as the stream progresses.
    score *= 1.0 + 0.4 * progress;

    score
}

