pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled by stream progress (dead space matters more later)
    let mut score = pr * (0.5 + 0.9 * progress);

    // Non-linear polynomial coupling of normalized post-residual with progress
    let x = norm_pr;
    let coupling = x * x * (1.0 - x) * (0.5 + progress);
    score += 30.0 * coupling;

    // Penalize post_residual that is too small to fit typical future items
    let small_gap = if pr > 0.0 { (1.0 - pr / item_size.max(1) as f64).max(0.0) } else { 0.0 };
    score += 8.0 * small_gap * small_gap * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual relative to item)
    score -= (item_size as f64 / cap) * (1.0 - norm_pr) * 6.0;

    // Lookahead: favor bins whose post_residual accommodates next item
    if next_item_size > 0 {
        if pr >= next_item_size as f64 {
            score -= 5.0 * (pr / cap);
        } else {
            score += 4.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: mildly penalize early, allow late when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs() / cap;
        score += 10.0 * (1.0 - progress) - 8.0 * progress + 5.0 * fragmentation;
    } else {
        // Prefer bins deviating favorably from mean residual (better balance)
        score += 2.0 * ((bin_residual as f64 - mean_residual) / cap);
    }

    // Slight preference for consolidating among many open bins
    score -= (open_bins_count as f64).ln() * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness-driven reward: quadratic in how full the bin becomes.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 52.0 * tightness * tightness * (1.0 + 0.6 * tightness);

    // Exact fits are gold.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 200.0 - (post_residual as f64) * 10.0;
    } else {
        let r = post_residual;
        let harmonic_bonus: f64 = if r % 50 == 0 {
            150.0
        } else if r % 25 == 0 {
            100.0
        } else if r % 10 == 0 {
            75.0
        } else if r % 5 == 0 {
            40.0
        } else {
            0.0
        };
        score -= harmonic_bonus;
        if r > 50 {
            score -= 30.0;
        } else if r < 15 {
            score += 50.0;
        }
    }

    // Lookahead: chain-fit quality for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 40.0 * chain_fit;
            if post_residual == next_item_size {
                score -= 80.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportional dead waste.
            let dead = post_residual as f64 / next_item_size as f64;
            let fill = item_size as f64 / cap;
            score += 34.0 * (1.0 - dead) * (1.0 - dead) * (0.6 + 0.8 * fill);
        }
    }

    // Last-chance bin: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 78.0 - 34.0 * progress - 10.0 * fragmentation;
        if next_item_size > 0 {
            let pair = item_size + next_item_size;
            if pair == bin_capacity {
                score -= 100.0;
            } else if pair <= bin_capacity {
                let slack = (bin_capacity - pair) as f64 / cap;
                score -= 44.0 * (1.0 - slack);
            } else if next_item_size as f64 > 0.75 * cap {
                score -= 10.0;
            }
        }
        if item_size as f64 > 0.6 * cap {
            score -= 18.0;
        }
        if fitting_bins_count <= 1 {
            score -= 28.0;
        }
        // Prefer reusing roomy open bins when they exist.
        if mean_residual > item_size as f64 + 10.0 {
            score += 60.0;
        }
    } else {
        // Penalize tiny nibbles into large residuals (fragmentation risk).
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
            score += 20.0 * (1.0 - fill_ratio);
        }
        // Penalize leaving a residual the next item cannot use, worse late in stream.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let leak = post_residual as f64 / cap;
            score += 14.0 * leak * (1.0 + progress);
        }
        // Protect residuals that exactly fit the next item against squandering.
        if next_item_size > 0 && bin_residual >= next_item_size
            && (bin_residual - next_item_size) < (item_size.max(1) / 2).max(1)
            && item_size < next_item_size {
            score += 26.0;
        }
    }

    // Stream phase: be greedier about exactness late in the stream.
    score *= 1.0 + 0.2 * progress;

    // Slight consolidation preference for below-average residual bins.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 10 bands.
    let class = (post_residual * 10 / bin_capacity.max(1)) as i64;
    // Dead-space penalty grows superlinearly for tiny unusable leftovers,
    // but class 0 (perfect fit) is heavily rewarded.
    score += match class {
        0 => -30.0,
        1 => 18.0,   // 1..10 leftover: nearly unusable dead space
        2 => 8.0,
        3 => 3.0,
        4 => 0.0,
        5 => -2.0,
        6 => -4.0,
        7 => -5.0,
        8 => -6.0,
        _ => -7.0,
    };

    // Exact-fit bonus: leftover that is a clean divisor fraction of capacity
    // (e.g. 50, 25, 20, 10) leaves a reusable harmonic slot.
    let pr = post_residual;
    if pr > 0 && bin_capacity % pr == 0 {
        score -= 6.0;
    }

    // Coupling with lookahead item: reward leftovers that can host the next item exactly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here; penalize tight fits that strand the bin
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets a mild baseline so it only wins
    // when open bins have genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0; // big next item: fresh bin may serve it well
