    }

    // Late in the stream, consolidate aggressively into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / cap);

    // Prefer bins below mean residual (tighter bins) slightly.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

