pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else {
            // residual harder to fill when below typical small-item size
            let waste = (post_residual as f64 / bin_capacity as f64).powi(2);
            score += 30.0 * waste;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly in post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 8.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Global pressure: many bins with high mean residual -> consolidate.
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual as f64 > mean_residual {
        score -= 12.0 * pressure;
    } else {
        score += 12.0 * pressure;
    }

    // Time horizon: late in stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 15.0 + 60.0 * progress;
        // but early stream, a fresh bin is fine for large items
        if item_size > 70 && progress < 0.3 {
            score -= 20.0;
        }
    } else {
        score -= 10.0 * progress;
    }

    // Prefer filling bins that are already substantially loaded.
    let load = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 20.0 * load * load;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 120.0;
    }

    // Tightness reward: quadratic in fill of the residual
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 52.0 * tightness * tightness * (1.0 + 0.6 * tightness);

    // Lookahead on next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 40.0 * chain_fit;
            if post_residual == next_item_size {
                score -= 80.0;
            }
        } else {
            // next item cannot fit here: penalize blocking dead space
            let dead = post_residual as f64 / next_item_size as f64;
            let fill = item_size as f64 / cap;
            score += 34.0 * (1.0 - dead) * (1.0 - dead) * (0.6 + 0.8 * fill);
        }
    }

    // Penalize tiny unusable residuals below plausible small-item sizes
    if post_residual > 0 && post_residual < 6 {
        score += 60.0;
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * ((fitting_bins_count as f64 - 1.0).ln().max(0.0));
    }

    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 78.0 - 34.0 * progress - 10.0 * fragmentation;
        if next_item_size > 0 {
            let pair = item_size + next_item_size;
            if pair == bin_capacity {
                score -= 100.0;
            } else if pair <= bin_capacity {
                let slack = (bin_capacity - pair) as f64 / cap;
                score -= 44.0 * (1.0 - slack);
            } else if next_item_size as f64 > 0.75 * cap {
                score -= 10.0;
            }
        }
        if item_size as f64 > 0.6 * cap {
            score -= 18.0;
        }
        if fitting_bins_count <= 1 {
            score -= 28.0;
        }
    } else {
        // Existing bin: discourage wasting large residuals on tiny items
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
            score += 20.0 * (1.0 - fill_ratio);
        }
        // Dead space that next item cannot use
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = post_residual as f64 / cap;
            score += 28.0 * wasted * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Reserve residual exactly matching next item when current item is small
        if next_item_size > 0 && bin_residual >= next_item_size
            && (bin_residual - next_item_size) < (item_size.max(1) / 2).max(1)
            && item_size < next_item_size {
            score += 26.0;
        }
        // Late-stream leak penalty for residuals next item can't use
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
            let leak = post_residual as f64 / cap;
            score += 14.0 * leak * (1.0 + progress);
        }
        // Late stream: prefer filling existing bins more aggressively
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let res = bin_residual as f64;

    let mut score = post;

    // Reward tight fits: quadratic coupling of post_residual with progress
    let tightness = 1.0 - (post / cap);
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize exact-fit waste only mildly when it leaves dead space unusable by next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            // next item cannot fit here: dead space penalty, stronger early
            score += 12.0 * (post / cap) * (1.0 - progress);
        } else {
            // next item fits: reward chain placements
            score -= 10.0 * (nxt / cap) * (0.3 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 3.0 * ((post - mean_residual) / cap);

    // Smooth new-bin candidate adjustment: empty bin gets slight bias toward reuse of open bins
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Non-linear polynomial coupling of item size with progress
    score -= 8.0 * (item / cap) * (item / cap) * progress;

    score
}

