        // Late-stream leak penalty: stranded residual matters more near the end.
        if post_residual > 0 && post_residual < next_item_size.max(1) && next_item_size > 0 {
            let progress = step_index as f64 / (total_items as f64).max(1.0);
            let leak = post_residual as f64 / cap;
            score += 14.0 * leak * (1.0 + progress);
        }
    }

    // Stream phase: be slightly greedier about exactness late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // Slight preference for bins with below-average residual (consolidate waste).
    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step chain: bin becomes exactly full later
        } else if post_residual > next_item_size {
            // next item fits too; reward tightness of the chain
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize dead space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer minimal waste
        score += 2.0 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin opening early in the stream when existing bins could fit.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        // but if no open bin fits, opening is fine: cancel penalty
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight preference for larger residual bins when many bins are open.
    score -= 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
