pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;

    // Base: prefer tight fits (low post-residual), with a mild convexity
    // penalty so that leaving 1-2 units of dead space is punished hard,
    // while moderately roomy leftovers are tolerated.
    let mut score = post + (post * post) / (4.0 * cap);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 3 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, this
    // is a great chain placement; if the next item barely misses, this
    // placement creates a trap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Reward chains, stronger the tighter the next fit.
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else {
            // Penalize stranding: post-residual too small for next item.
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = 1.0 - (post / cap);
        score -= 20.0 * fit_quality;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is large relative to the empty capacity or existing
    // bins are crowded (mean residual low) and few bins fit the item.
    if bin_residual == bin_capacity {
        // Neutral base for empty bin; adjust by global pressure.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        // Opening new bins early with small items wastes potential;
        // penalize more when mean residual across open bins is high.
        score += 14.0 * (1.0 - pressure) * (1.0 - progress);
        // Slight reward for opening a bin when nothing fits well.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
        // Large items into fresh bins are fine.
        score -= 6.0 * (item / cap);
    }

    // Mild global regularization: prefer bins with residual near the
    // mean (keeps the bin pool homogeneous and flexible).
    let dev = (residual - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling bins that are already relatively full (larger item
    // fraction of residual) to consolidate waste.
    score -= 5.0 * (item / residual.max(1.0));

    // Time horizon: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
