pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling: dead space penalized more as stream progresses
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits with smooth term
    let tight = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score -= 30.0 * (1.0 - tight * tight);

    // Last-chance bonus, smoothed
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: favor leaving space for next item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.3 * gap * gap / cap;
    }

    // Slight preference for bins below mean residual early, above late
    score += (pr - mean_residual) * (0.1 - 0.2 * progress);

    // Penalize proliferating bins mildly
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
