pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by quarter-capacity bands.
    let q = post_residual * 4 / bin_capacity; // 0..3 harmonic class
    match q {
        0 => score -= 25.0,                      // near-perfect fit: strongly reward
        1 => score += 5.0,                       // awkward small gap: penalize slightly
        2 => score -= 3.0,                       // medium gap usable
        _ => score -= 10.0,                      // large gap still flexible
    }

    // Dead-space penalty: tiny but nonzero leftover (unusable for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect closure bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // chain placement possible
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 8.0; // next item nearly closes the bin
            }
        } else {
            score += 6.0; // next item cannot follow here
        }
        // Harmonic divisibility: next item divides post_residual evenly
        if post_residual % next_item_size.max(1) == 0 && next_item_size > 0 {
            score -= 7.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitter
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly discouraged unless stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 30.0 * (1.0 - progress);
    }

    // Tie-break toward tighter bins overall
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: quadratic + cubic boost, favors snug fills
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 55.0 * tightness * tightness * (1.0 + 0.6 * tightness);

    // Perfect fit: unbeatable
    if post_residual == 0 {
        score -= 120.0;
    }

    // Lookahead chain: next item interplay with post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 42.0 * chain_fit;
            if post_residual == next_item_size {
                score -= 80.0;
            }
        } else {
            // Next item cannot fit: penalize blocking dead space
            let dead = post_residual as f64 / next_item_size as f64;
            let fill = item_size as f64 / cap;
            score += 34.0 * (1.0 - dead) * (1.0 - dead) * (0.6 + 0.8 * fill);
        }
    }

    // Small unusable residual penalty (min item size is 1, but keep threshold small)
    if post_residual > 0 && post_residual < 4 {
        score += 90.0;
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * ((fitting_bins_count as f64 - 1.0).ln().max(0.0));
    }

    // New-bin candidate logic
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 78.0 - 34.0 * progress - 10.0 * fragmentation;
        // Pair lookahead: opening a bin for item + next item exactly is great
        if next_item_size > 0 {
            let pair = item_size + next_item_size;
            if pair == bin_capacity {
                score -= 100.0;
            } else if pair <= bin_capacity {
                let slack = (bin_capacity - pair) as f64 / cap;
                score -= 44.0 * (1.0 - slack);
            } else if next_item_size as f64 > 0.75 * cap {
                score -= 10.0;
            }
        }
        // Large items deserve fresh bins when nothing fits well
        if item_size as f64 > 0.6 * cap {
            score -= 18.0;
        }
        if fitting_bins_count <= 1 {
            score -= 28.0;
        }
    } else {
        // Existing bin: discourage tiny fills into large residuals
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
            score += 20.0 * (1.0 - fill_ratio);
        }
        // Penalize leaving a residual that next item can't use
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let wasted = post_residual as f64 / cap;
            score += 28.0 * wasted * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Reserve-space guard: next item would leave a sub-half-item sliver
        if next_item_size > 0 && bin_residual >= next_item_size
            && (bin_residual - next_item_size) < (item_size.max(1) / 2).max(1)
            && item_size < next_item_size {
            score += 26.0;
        }
        // Late-stream leak penalty grows with progress
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let leak = post_residual as f64 / cap;
            score += 14.0 * leak * (1.0 + progress);
        }
        // Late stream: reward using existing bins more aggressively
        score -= 40.0 * progress;
    }

    score
}

