    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward good tight fits generally (small post_residual relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Dead space is worse if the gap cannot fit even the smallest plausible next item.
    if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) {
        score += 15.0;
    }
    // Bonus if this placement leaves room exactly for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and penalize opening yet another bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += 12.0 * pressure;

    // New-bin candidate: make it unattractive unless existing fits are terrible
    // (handled implicitly by dead-space penalties) or bins are very fragmented.
    if bin_residual == bin_capacity {
        score += 35.0 + 8.0 * open_bins_count as f64;
        // Late in the stream, opening a fresh bin is more acceptable for big items.
        if item_size > 60 {
            score -= 20.0 * progress;
        }
    }

    // Last-chance bin: strongly favor using it to avoid waste of an almost-fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild alignment with mean residual: prefer bins whose residual is below average
    // (i.e., more filled bins), keeping near-empty bins for future large items.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
