            else if pr % 5 == 0 { 15.0 } // half-decile harmonic
            else { 0.0 }
        }
    };
    score -= class_bonus;

    // Integer-division harmonic: residual in the "small item band" [10,30]
    // is reusable by the smallest item class; penalize mid-band waste.
    if pr >= 10 && pr <= 30 {
        score -= 20.0 - (pr as f64 / 3.0);
    } else if pr > 30 && pr < 50 {
        score += 10.0; // dead zone: too big to waste, too small for mid items
    }

