    // New-bin candidate handling: neutral baseline, but discourage opening
    // a fresh bin when the current one leaves a harmonic (round) residual.
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big next item: fresh bin is attractive
