    // Prefer bins whose residual is below mean (use up the cramped ones first).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Cap open-bin proliferation slightly when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

