    } else {
        // Discourage dumping tiny items into large-residual bins (fragmentation guard).
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
            score += 20.0 * (1.0 - fill_ratio);
