        if progress > 0.7 && open_bins_count > 8 {
            score += 25.0;
        }
    } else {
        // Penalize small items into large residuals (poor fill ratio), but
        // relax when the residual is a "dead" size that nothing else fits.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
            let usable = if next_item_size > 0 && (next_item_size as u32) <= bin_residual - item_size {
                0.5
            } else {
                1.0
            };
            score += 20.0 * (1.0 - fill_ratio) * usable;
        }
        // Reward near-perfect fills: leaving <2% waste is excellent compaction.
        if post_residual > 0 && (post_residual as f64) < 0.02 * cap {
            score -= 60.0;
        }
    }

    // Stream phase: late in the stream, be greedy about exactness.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // Consolidate waste: prefer bins with below-average residual, scaled by
    // how far below average they are (stronger pull toward tightest bins).
    if (bin_residual as f64) < mean_residual {
        let depth = (mean_residual - bin_residual as f64) / cap;
        score -= 10.0 + 40.0 * depth.min(0.25);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (10)
    // are pure waste — penalize them quadratically.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 12.0;
    } else if post_residual < 20 {
        // Small gaps (20..30 residual band) are hard to fill with items >= 10.
        score += (20 - post_residual) as f64 * 4.0;
    } else if post_residual >= 40 {
        // Large leftover space is flexible: reward keeping it.
        score -= (post_residual as f64 - 40.0).min(30.0) * 0.6;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new bin is relatively cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; but attractive if the
        // item is large and would leave a tiny unusable gap elsewhere.
        score += 25.0 + pressure * 6.0;
        if item_size > 60 {
            score -= 15.0;
        }
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 8.0; // dead space relative to the known next item
    }

    // Mild preference for bins tighter than average (best-fit coupling).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) but normalize against capacity.
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
