    // 2-step lookahead: exact fill by next item is excellent
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // snugness of the next fit
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
            // extra reward if next item also lands on a harmonic residual
            let nr = post_residual - next_item_size;
            if nr > 0 && (nr % 10 == 0 || nr % 5 == 0) {
                score -= 40.0;
            }
        } else {
            // next item can't fit here: penalize blocking dead space, scaled by gap
            score += 30.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 80.0;
        // Opening a new bin is attractive when next item is large and fits poorly elsewhere
        if next_item_size > 0 && next_item_size > post_residual.max(1) && fitting_bins_count <= 1 {
            score -= 100.0;
        }
        // Late in stream: be conservative, keep filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * progress;
    }

    // Prefer tighter bins relative to mean residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;

