    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64 ;
        score = waste ;
        // lookahead: if next item also fits the leftover, a fresh bin is fine
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0 ;
        }
        if fitting_bins_count <= 1 {
            score -= 400.0 ; // no open bin can take it -> must open
        } else {
            score += 120.0 ; // prefer reusing an existing fit
        }
        return score ;
    }

    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 10 {
        score -= 200.0 - (post_residual as f64) * 10.0 ;
    } else {
        let r = post_residual ;
        let harmonic_bonus : f64 = if r % 50 == 0 { 150.0 }
            else if r % 25 == 0 { 100.0 }
            else if r % 10 == 0 { 75.0 }
            else if r % 5 == 0 { 40.0 }
            else { 0.0 } ;
        score -= harmonic_bonus ;
        if r > 50 {
            score -= 30.0 ;
            // large leftovers are better when the next item can use them
            if next_item_size as f64 <= r as f64 {
                score -= 25.0 ;
            } else {
                score += 10.0 ;
            }
        } else if r < 15 {
            score += 50.0 ;
        }
        // penalize tight leftovers that cannot host the next item
        if (r as u32) < next_item_size && r < 25 {
            score += 15.0 ;
        }
        // when many bins fit, prefer the one leaving the most structured space
        if fitting_bins_count > 3 {
            score -= (r / 10) as f64 * 4.0 ;
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
