            // next item still fits: reward proportionally to how snugly
            let snug = nxt / post_residual as f64;
            score -= 25.0 * snug * snug;
        } else {
            // next item won't fit: penalize leaving awkward small residual
            let dead = post_residual as f64 / bin_capacity as f64;
            if dead > 0.0 && dead < 0.10 {
                score += 20.0 * (0.10 - dead);
