pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0 - (post_residual as f64) * 10.0;
    } else {
        let r = post_residual;
        let harmonic_bonus: f64 = if r % 50 == 0 { 160.0 } else if r % 25 == 0 { 105.0 } else if r % 10 == 0 { 80.0 } else if r % 5 == 0 { 45.0 } else { 0.0 };
        score -= harmonic_bonus;
        if r > 50 { score -= 35.0; } else if r < 15 { score += 55.0; }
        let consumed = item_size as f64;
        let dead_ratio = (r as f64) / (consumed + r as f64 + 1.0);
        score += 30.0 * dead_ratio * dead_ratio;
        if r > consumed as u32 * 2 && r > 30 { score += 18.0; }
        if next_item_size > 0 && r > next_item_size && r - next_item_size <= 12 {
            score += 9.0 - 0.5 * (r - next_item_size) as f64;
        }
        let half_cap = bin_capacity / 2;
        if r > half_cap && r <= half_cap + 8 { score += 7.0; }
        let third_cap = bin_capacity / 3;
        if r > third_cap && r <= third_cap + 5 { score += 4.0; }
        if next_item_size > 0 && r == next_item_size && fitting_bins_count <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
    }
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 9.0 * fit_ratio * fit_ratio;
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += (4.0 + 2.0 * (fitting_bins_count.min(4) as f64)) * dead
                + 2.0 * dead * dead / (next_item_size as f64).max(1.0);
        } else if post_residual == next_item_size {
            score -= 135.0;
        } else {
            let second_gap = post_residual - next_item_size;
            let mut bonus = 4.0;
            if second_gap <= 20 { bonus += 15.0; }
            if second_gap <= next_item_size * 2 { bonus += 6.0; }
            if second_gap == 0 && fitting_bins_count <= 2 { bonus += 25.0; }
            if second_gap <= 6 && post_residual <= bin_capacity / 3 { bonus += 8.0; }
            bonus -= 5.0 * progress * (second_gap as f64 / 20.0).min(1.0);
            score -= bonus;
        }
    }
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let next_pressure = (next_item_size as f64 / bin_capacity as f64).clamp(0.0, 1.0);
        score += 22.0 - 15.0 * fragmentation - 9.0 * progress + 6.0 * next_pressure;
        score += 8.0 * progress * (1.0 - fragmentation);
        if progress > 0.7 && open_bins_count > 4 { score += 10.0 * (1.0 - fragmentation); }
        if progress > 0.85 && fitting_bins_count <= 1 { score -= 12.0; }
        if mean_residual >= next_item_size as f64 && fitting_bins_count >= 1 {
            score += 16.0 * (1.0 - next_pressure);
        }
    } else if post_residual > 0 && post_residual < 6 && next_item_size > post_residual {
        score += 14.0 - 2.0 * post_residual as f64;
    }
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.04 * dev;
    score -= 0.02 * open_bins_count as f64 * (1.0 - fit_ratio);
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 25.0 * scarcity;
    }
    if fitting_bins_count <= 2 && post_residual > item_size {
        score += 6.0 * (post_residual - item_size) as f64 / (bin_capacity as f64);
    }
    if post_residual > 0 && post_residual <= 3 {
        score -= 30.0 * (0.5 + progress);
    }
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        if leftover_after_next > 0 && leftover_after_next < next_item_size {
            score -= 0.5 * (next_item_size - leftover_after_next) as f64;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0 - (post_residual as f64) * 10.0;
    } else {
        let r = post_residual;
        let harmonic_bonus: f64 = if r % 50 == 0 { 155.0 } else if r % 25 == 0 { 105.0 } else if r % 10 == 0 { 78.0 } else if r % 5 == 0 { 42.0 } else { 0.0 };
        score -= harmonic_bonus;
        if r > 50 {
            score -= 32.0;
        } else if r < 15 {
            score += 52.0;
        }
        // Dead-space ratio term (borrowed direction from best).
        let consumed = item_size as f64;
        let dead_ratio = (r as f64) / (consumed + r as f64 + 1.0);
        score += 28.0 * dead_ratio * dead_ratio;
        if r > consumed as u32 * 2 && r > 30 {
            score += 16.0;
        }
        // Sweet spot: leaves a small gap that next item nearly fills.
        if next_item_size > 0 && r > next_item_size && r - next_item_size <= 12 {
            score += 9.0 - 0.5 * (r - next_item_size) as f64;
        }
        let half_cap = bin_capacity / 2;
        if r > half_cap && r <= half_cap + 8 {
            score += 7.0;
        }
        let third_cap = bin_capacity / 3;
        if r > third_cap && r <= third_cap + 5 {
            score += 4.0;
        }
    }

    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    if next_item_size > 0 {
        if post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += 4.0 * dead + 2.0 * dead * dead / (next_item_size as f64).max(1.0);
        } else if post_residual == next_item_size {
            score -= 130.0 + 20.0 * (1.0 - progress);
        } else {
            let second_gap = post_residual - next_item_size;
            let mut bonus = 3.0;
            if second_gap <= 20 {
                bonus += 14.0;
            }
            if second_gap <= next_item_size as u32 * 2 {
                bonus += 5.0;
            }
            if second_gap <= 6 && post_residual <= bin_capacity / 3 {
                bonus += 8.0;
            }
            bonus -= 4.0 * progress * (second_gap as f64 / 20.0).min(1.0);
            score -= bonus;
        }
    }

    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 20.0 - 14.0 * fragmentation - 8.0 * progress;
        // Discourage new bins when many open bins fit well.
        if fitting_bins_count > 2 {
            score += 6.0 * (fitting_bins_count as f64 - 2.0).min(3.0);
        }
    }

    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;
    score -= 0.02 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Nearly-closed bins: strong push to finish them.
    if post_residual > 0 && post_residual <= 3 {
        score -= 30.0 * (0.5 + progress);
    }

    score *= 1.0 + 0.5 * progress;
    score
}

