pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0 - (post_residual as f64) * 10.0;
    } else {
        let r = post_residual;
        let harmonic: f64 = if r % 50 == 0 { 160.0 }
            else if r % 25 == 0 { 105.0 }
            else if r % 10 == 0 { 80.0 }
            else if r % 5 == 0 { 45.0 }
            else { 0.0 };
        score -= harmonic;
        if r > 50 { score -= 35.0; }
        else if r < 15 { score += 55.0; }

        // dead-space ratio relative to what was just consumed
        let consumed = item_size as f64;
        let dead_ratio = (r as f64) / (consumed + r as f64 + 1.0);
        score += 30.0 * dead_ratio * dead_ratio;
        if r > consumed as u32 * 2 && r > 30 { score += 18.0; }

        // residual slightly larger than next item wastes the gap
        if next_item_size > 0 && r > next_item_size && r - next_item_size <= 12 {
            score += 9.0 - 0.5 * (r - next_item_size) as f64;
        }

        // residual near half/third capacity splits well
        let half_cap = bin_capacity / 2;
        if r > half_cap && r <= half_cap + 8 { score += 7.0; }
        let third_cap = bin_capacity / 3;
        if r > third_cap && r <= third_cap + 5 { score += 4.0; }

        if next_item_size > 0 && r == next_item_size && fitting_bins_count <= 3 {
            score -= 22.0 * (1.0 - progress);
        }

        // penalize residuals far above mean upcoming demand
        let mr = mean_residual.max(1.0);
        if r as f64 > mr * 1.6 {
            score += 6.0 * ((r as f64 - mr * 1.6) / bin_capacity as f64);
        }
    }

    // lookahead interaction with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 140.0;
        } else if post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += 4.0 * dead + 2.0 * dead * dead / (next_item_size as f64).max(1.0);
        } else {
            let gap = post_residual - next_item_size;
            let mut bonus = 4.0;
            if gap <= 20 { bonus += 15.0; }
            if gap <= next_item_size * 2 { bonus += 6.0; }
            if gap <= 6 && post_residual <= bin_capacity / 3 { bonus += 8.0; }
            bonus -= 5.0 * progress * ((gap as f64) / 20.0).min(1.0);
            score -= bonus;
        }
        // slack-based lookahead: prefer bins where next item fits with minimal slack
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + slack * 0.15);
        }
    }

    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }
    if post_residual > 0 && post_residual <= 3 {
        score -= 30.0 * (0.5 + progress);
    }

    // last chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // new-bin candidate: only attractive when few fitting bins exist
    if bin_residual == bin_capacity && post_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { (1.0 / fitting_bins_count as f64).min(1.0) };
        score += 55.0 - 45.0 * scarcity * (1.0 - progress);
        if next_item_size > 0 && next_item_size > post_residual.max(1) && fitting_bins_count <= 1 {
            score -= 110.0;
        }
    } else {
        score -= 40.0 * progress;
    }

    // tighter-than-mean residual preference
    score -= 0.5 * (mean_residual - post_residual as f64);
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.04 * dev;

    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 9.0 * fit_ratio * fit_ratio;
    score += 0.02 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

