pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0 - (post_residual as f64) * 10.0;
    } else {
        let r = post_residual;
        let harmonic_bonus: f64 = if r % 50 == 0 { 160.0 } else if r % 25 == 0 { 105.0 } else if r % 10 == 0 { 80.0 } else if r % 5 == 0 { 45.0 } else { 0.0 };
        score -= harmonic_bonus;
        if r > 50 {
            score -= 35.0;
        } else if r < 15 {
            score += 55.0;
        }
        // Dead-space ratio term.
        let consumed = item_size as f64;
        let dead_ratio = (r as f64) / (consumed + r as f64 + 1.0);
        score += 30.0 * dead_ratio * dead_ratio;
        if r > consumed as u32 * 2 && r > 30 {
            score += 18.0;
        }
        // Sweet spot: leaves a small gap that next item nearly fills.
        if next_item_size > 0 && r > next_item_size && r - next_item_size <= 12 {
            score += 9.0 - 0.5 * (r - next_item_size) as f64;
        }
        let half_cap = bin_capacity / 2;
        if r > half_cap && r <= half_cap + 8 {
            score += 7.0;
        }
        let third_cap = bin_capacity / 3;
        if r > third_cap && r <= third_cap + 5 {
            score += 4.0;
        }
        // Penalize residuals far above mean upcoming demand (dead space).
        let mr = mean_residual.max(1.0);
        if r as f64 > mr * 1.6 {
            score += 6.0 * ((r as f64 - mr * 1.6) / bin_capacity as f64);
        }
        // Exact-match lookahead: post-residual equals next item size.
        if next_item_size > 0 && r == next_item_size && fitting_bins_count <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 9.0 * fit_ratio * fit_ratio;

    if next_item_size > 0 {
        if post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += 4.0 * dead + 2.0 * dead * dead / (next_item_size as f64).max(1.0);
        } else if post_residual == next_item_size {
            score -= 135.0;
        } else {
            let second_gap = post_residual - next_item_size;
            let mut bonus = 4.0;
            if second_gap <= 20 {
                bonus += 15.0;
            }
            if second_gap <= next_item_size as u32 * 2 {
                bonus += 6.0;
            }
            if second_gap == 0 && fitting_bins_count <= 2 {
                bonus += 25.0;
            }
            if second_gap <= 6 && post_residual <= bin_capacity / 3 {
                bonus += 8.0;
            }
            bonus -= 5.0 * progress * (second_gap as f64 / 20.0).min(1.0);
            score -= bonus;
        }
        // Slack-based lookahead: prefer bins where next item fits with minimal waste.
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + slack * 0.15);
        }
    }

    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        if post_residual == bin_capacity {
            let scarcity = if fitting_bins_count == 0 { 1.0 } else { (1.0 / fitting_bins_count as f64).min(1.0) };
