        let r = post_residual;
        let harmonic: f64 = if r % 50 == 0 { 160.0 }
            else if r % 25 == 0 { 105.0 }
            else if r % 10 == 0 { 80.0 }
            else if r % 5 == 0 { 45.0 }
            else { 0.0 };
        score -= harmonic;
        if r > 50 { score -= 35.0; }
        else if r < 15 { score += 55.0; }

        // Dead-space ratio penalty (borrowed refinement)
        let consumed = item_size as f64;
        let dead_ratio = (r as f64) / (consumed + r as f64 + 1.0);
        score += 30.0 * dead_ratio * dead_ratio;
        if r > consumed as u32 * 2 && r > 30 { score += 18.0; }

        // Penalize residual slightly too large to pair with next item
        if next_item_size > 0 && r > next_item_size {
            let gap = (r - next_item_size) as f64;
            if gap <= 25.0 {
                score += 0.45 * gap * (1.0 - 0.6 * progress);
            }
        }
        // Reward residuals that can host next item plus a small remainder
        if next_item_size > 0 && r >= next_item_size && r <= next_item_size * 2 {
            score -= 10.0;
        }
        // Capacity-fraction sweet spots
        let half_cap = bin_capacity / 2;
        if r > half_cap && r <= half_cap + 8 { score += 7.0; }
        let third_cap = bin_capacity / 3;
        if r > third_cap && r <= third_cap + 5 { score += 4.0; }
    }

    // Lookahead with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 135.0;
            if fitting_bins_count <= 2 { score -= 25.0; }
        } else if post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += 4.0 * dead + 2.0 * dead * dead / (next_item_size as f64).max(1.0);
        } else {
            let gap = post_residual - next_item_size;
            let mut bonus = 4.0;
            if gap <= 20 { bonus += 15.0; }
            if gap <= next_item_size as u32 * 2 { bonus += 6.0; }
            if gap <= 6 && post_residual <= bin_capacity / 3 { bonus += 8.0; }
            bonus -= 5.0 * progress * ((gap as f64) / 20.0).min(1.0);
            score -= bonus;
            let slack = gap as f64;
            score -= 12.0 / (1.0 + slack * 0.15);
        }
    }

    // Tiny unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }
    if post_residual > 0 && post_residual <= 3 {
        score -= 30.0 * (0.5 + progress);
    }

    // Last chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin decision: open only when fragmentation is high and next item is large
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let next_pressure = (next_item_size as f64 / bin_capacity as f64).clamp(0.0, 1.0);
        score += 70.0 - 25.0 * fragmentation - 20.0 * progress + 12.0 * next_pressure;
        if next_item_size > 0 && next_item_size > post_residual.max(1) && fitting_bins_count <= 1 {
            score -= 110.0;
        }
    } else {
        score -= 40.0 * progress;
    }

    // Tighter-than-mean preference and deviation penalty
    score -= 0.5 * (mean_residual - post_residual as f64);
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.04 * dev;

    // Quadratic fit-ratio shaping (from best) and mild spread pressure
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 9.0 * fit_ratio * fit_ratio;
    score += 0.02 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}
